sp_widget.client_script:
api.controller = function (DHManagerService, $scope, $timeout) {
	var c = this;
	c.loading = null;
	c.actions = [];

	$scope.$watch(
		() => DHManagerService.assetsLoading,
		(loading) => (c.loading = loading),
	);

	c.$onInit = function () {
		$scope.$watch(
			() => DHManagerService.state.selectedAsset,
			function (newVal) {
				c.loading = true;
				$timeout(() => {
					if (!newVal) return;
					c.selectedAsset = newVal;
					c.actions = DHManagerService.getSelectedAssetInfo()?.actions?.filter(
						(action) => action.category === "performance",
					);
					c.loading = false;

				}, 100);

			},
		);

		// DHManagerService.getDexScores().then(
		//   (r) => {
		//     var dexScores = r?.data;
		//     c.currentDexScore =
		//       dexScores && dexScores.length > 0
		//         ? Math.floor(dexScores[0].dex_score)
		//         : 0;
		//     c.displayLogAnIssueAction =
		//       c.currentDexScore <= 45 && c.data.enable_log_an_issue_action;
		//   },
		//   (e) => console.error(e)
		// );
	};

	c.getIcon = function (action) {
		switch (action.type) {
			case "remote_action":
				return "fa-medkit";
			case "url":
			case "page":
				return "fa-external-link";
			case "client_script":
				return "fa-cogs";
			case "server_script":
				return "fa-cogs";
			default:
				return "fa-arrow-right";
		}
	};

	c.runAction = async function (action) {

		const device = DHManagerService.getSelectedAssetInfo();
		if (!device) return;

		if (
			action.type == "page" ||
			action.type == "url" ||
			action.type == "client_script"
		) {
			console.log("Logging action", action);
			logActionExecution(action, device);
		}

		device.executeAction(action);
	};

	function logActionExecution(action, device) {
		c.server.get({
			action: "log-action",
			data: {
				device,
				action,
			},
		});
	}
};

sp_widget.css:
.error-display {
    display: flex;
    flex-direction: column;
    justify-items: center;
    align-items: center;
    font-size: large;
    font-weight: bold;
    gap: 20px;

    img {
        max-width: 450px;
        max-height: 150px;
    }
}

.loading {
    min-height: 15rem;
    width: 100%;
    border-radius: 1rem;
    background: #f6f7f8;
    background-image: linear-gradient(to right, #f6f7f8 0%, #edeef1 20%, #f6f7f8 40%, #f6f7f8 100%);
    background-repeat: no-repeat;
    background-size: 100rem 28rem;
    animation: shimmer 2s infinite linear;
 }

@keyframes shimmer {
    0% {
        background-position: -1000px 0;
    }

    100% {
        background-position: 1000px 0;
    }
}

.action {
    display: flex;
    justify-content: space-between;
    align-items: center;
    gap: 10px;
    border-radius: 5px;
    padding: 10px;
    margin: 10px;
    border: 1px solid rgba(101, 110, 129, .5);

    .text {
        .title {
            font-size: large;
            font-weight: bold;
        }
    }
}

